changeSet.sql:
create or replace procedure ${database_name}.trading_use_case.sp_load_bronze_to_departments() returns varchar language sql execute as caller as $$ begin
merge into ${database_name}.trading_use_case.departments_silver as tgt using ( select distinct dept_id, dept_name, dept_code from ${database_name}.trading_use_case.employee_information_bronze ) as src on tgt.dept_id = src.dept_id
when matched then update set tgt.dept_name = src.dept_name, tgt.dept_code = src.dept_code
when not matched then insert ( dept_id, dept_name, dept_code ) values ( src.dept_id, src.dept_name, src.dept_code );
return 'departments silver loaded successfully';
end; $$;
